package io.withlambda.ktor2.server.bind

import io.ktor.http.ContentType
import io.ktor.http.HttpStatusCode
import io.ktor.server.application.Application
import io.ktor.server.application.call
import io.ktor.server.response.respond
import io.ktor.server.response.respondText
import io.ktor.server.routing.get
import io.ktor.server.routing.routing

/**
 * Installs a `GET /openapi.json` route that serves the OpenAPI specification generated by the
 * KSP processor at compile time.
 *
 * The file is loaded from the classpath at `/openapi.json`. When no such resource is found
 * (e.g., the KSP processor has not run or no [@ApiController][ApiController]-annotated classes
 * exist), the route responds with [HttpStatusCode.NotFound].
 *
 * ### Usage
 * ```kotlin
 * fun Application.module() {
 *     installOpenApiRoute()
 * }
 * ```
 */
fun Application.installOpenApiRoute() {
    routing {
        get("/openapi.json") {
            // javaClass.getResourceAsStream is used instead of ClassLoader.getResourceAsStream
            // because the leading slash anchors the lookup to the root of the classpath,
            // which is where the KSP code-generator places the generated openapi.json.
            val content = javaClass.getResourceAsStream("/openapi.json")
                ?.bufferedReader()
                ?.readText()
            if (content != null) {
                call.respondText(content, ContentType.Application.Json)
            } else {
                call.respond(HttpStatusCode.NotFound)
            }
        }
    }
}
